import os


def load_or_seed(conn, path='/data/config.yaml'):
    row = conn.fetch_config()
    if row:
        return row
    if os.path.exists(path):
        return conn.seed_from(path)
    return conn.seed_default()

from chatbot.config.pg_store import load_or_seed


class C:
    def fetch_config(self):
        return None

    def seed_default(self):
        return {'bots': []}


def test_seed_default():
    assert load_or_seed(C(), '/nonexistent') == {'bots': []}
